+    format!(
+        r#"change_id.short({}) ++ "\n"
+        ++ local_bookmarks.map(|b| b.name()).join("\x1e") ++ "\n"
+        ++ remote_bookmarks.filter(|b| b.tracked()).map(|b| b.name() ++ "\x1f" ++ b.tracking_ahead_count().lower() ++ "\x1f" ++ b.tracking_behind_count().lower()).join("\x1e") ++ "\n"
