+                .bookmarks
+                .iter()
+                .map(|b| {
+                    let mut s = b.name.clone();
+                    let local_ahead = b.remote_behind;
+                    let local_behind = b.remote_ahead;
+                    let tracked_diverged = b.is_tracked && (local_ahead > 0 || local_behind > 0);
+                    if tracked_diverged {
+                        s.push('*');
