+                "bookmarks" => bookmarks.as_deref().map(Ok),
+                "conflicted" => conflicted.map(Ok),
+                "divergent" => divergent.map(Ok),
+                "hidden" => hidden.map(Ok),
+                "immutable" => immutable.map(Ok),
